<script lang="ts">
 import {useLocale,text} from '$lib/shared/presentation/locale';
 import {copy,noticeText,failureCode} from '$lib/shared/presentation/copy';
 const {locale,change:changeLanguage}=useLocale();
 import {notificationGroups} from '../application/groups';
 import {onMount,untrack} from 'svelte';
 import {NotificationFeed} from '../application/feed';
 import type {Notification,NotificationsGateway} from '../application/notifications';
 let {gateway}:{gateway:NotificationsGateway}=$props();
 let version=$state(0);
 const feed=new NotificationFeed(untrack(()=>gateway),()=>version++);
 const unreadOnly=$derived.by(()=>{version;return feed.unreadOnly;});
 const account=$derived.by(()=>{version;return feed.account;}),items=$derived.by(()=>{version;return feed.items;}),busy=$derived.by(()=>{version;return feed.busy;}),more=$derived.by(()=>{version;return feed.more;}),message=$derived.by(()=>{version;return feed.error;});
 function load(after=''){return feed.load(after);}
 function read(item:Notification){return feed.read(item);}
 onMount(()=>{const stop=gateway.watchAccountChange?.(()=>{feed.reset();void feed.load();});void feed.load();return()=>{stop?.();feed.close();};});

</script>
<svelte:head><title>{copy($locale,"Хабарлар — Qmanga")}</title><meta name="robots" content="noindex"/></svelte:head><h1>{copy($locale,"Хабарлар")}</h1><p class="muted">{text($locale,'Жаңа тараулар, пікірге жауаптар және жарияланым туралы шешімдер.','Новые главы, ответы на комментарии и решения по публикациям.')}</p>
<div class="notification-filter"><button class="button" aria-pressed={!unreadOnly} onclick={()=>feed.setUnread(false)}>{text($locale,'Барлығы','Все')}</button><button class="button" aria-pressed={unreadOnly} onclick={()=>feed.setUnread(true)}>{text($locale,'Оқылмаған','Непрочитанные')}</button></div>
{#if message}<p class="form-message" role="status">{noticeText($locale,message)}</p><button class="button" disabled={busy} onclick={()=>load(feed.cursor)}>{text($locale,'Қайталау','Повторить')}</button>{/if}{#if !account&&!busy}<p>{copy($locale,"Хабарларды көру үшін ")}<a class="auth-link" href="/login?returnTo=%2Fnotifications">{copy($locale,"кіріңіз")}</a>.</p>{/if}
{#each notificationGroups(items) as group}{#if group.length>1}<h2 class="group-title"><a href={'/titles/'+encodeURIComponent(group[0].titleSlug)}>{group[0].body.split(' · ')[0]}</a> · {group.length} {text($locale,'жаңа тарау','новых глав')}</h2>{/if}{#each group as item}<article class:unread={!item.read}>{#if !item.read}<span class="unread-label">{text($locale,'Оқылмаған','Не прочитано')}</span>{/if}<h2>{item.kind==='new_release'?text($locale,'Жаңа тарау','Новая глава'):item.kind==='comment_reply'?text($locale,'Пікірге жауап','Ответ на комментарий'):item.kind==='publication_published'?text($locale,'Тарау жарияланды','Глава опубликована'):item.kind==='publication_rejected'?text($locale,'Тарау түзетуге қайтарылды','Глава возвращена на исправление'):item.kind==='publication_withdrawn'?text($locale,'Тарау оқудан алынды','Глава снята с публикации'):item.kind==='project_request_approved'?text($locale,'Жоба өтінімі мақұлданды','Заявка на проект одобрена'):item.kind==='project_request_rejected'?text($locale,'Жоба өтінімі қайтарылды','Заявка на проект возвращена'):copy($locale,'Хабарлар')}</h2><p lang="kk">{item.body}</p><time datetime={item.createdAt}>{new Date(item.createdAt).toLocaleString($locale==='ru'?'ru-RU':'kk-KZ')}</time><div>{#if item.kind==='comment_reply'&&item.commentId&&(item.releaseId||item.titleSlug)}<a class="button primary" href={item.releaseId?`/read/${encodeURIComponent(item.releaseId)}?comment=${encodeURIComponent(item.commentId)}`:`/titles/${encodeURIComponent(item.titleSlug)}?tab=comments&comment=${encodeURIComponent(item.commentId)}`} onclick={()=>read(item)}>{text($locale,'Жауапты ашу','Открыть ответ')}</a>{:else if item.projectId}<a class="button primary" href={'/studio/projects/'+encodeURIComponent(item.projectId)} onclick={()=>read(item)}>{text($locale,'Жобаны ашу','Открыть проект')}</a>{:else if item.kind.startsWith('project_request_')}<a class="button subtle" href="/studio/requests" onclick={()=>read(item)}>{text($locale,'Өтінімдерді ашу','Открыть заявки')}</a>{:else if item.releaseId}<a class="button primary" href={`/read/${encodeURIComponent(item.releaseId)}`} onclick={()=>read(item)}>{copy($locale,"Оқу")}</a>{:else if item.titleSlug}<a class="button subtle" href={`/titles/${encodeURIComponent(item.titleSlug)}`} onclick={()=>read(item)}>{copy($locale,"Тайтлды ашу")}</a>{/if}{#if !item.read}<button class="button subtle" onclick={()=>read(item)}>{copy($locale,"Оқылды деп белгілеу")}</button>{/if}</div></article>{/each}{:else}{#if account&&!busy}<p class="empty-state">{copy($locale,"Әзірге хабар жоқ.")}</p>{/if}{/each}{#if more}<button class="button" onclick={()=>load(feed.cursor)} disabled={busy}>{copy($locale,"Тағы жүктеу")}</button>{/if}{#if busy}<p role="status">{copy($locale,"Жүктелуде…")}</p>{/if}
<style>.notification-filter{display:flex;gap:8px;margin-block:16px}.notification-filter [aria-pressed=true]{border-color:var(--accent)}.group-title{font-size:20px;margin-top:24px}.group-title a{display:inline-flex;align-items:center;min-height:44px}h1{font-size:26px}article{border:1px solid var(--line);border-radius:8px;background:var(--panel);padding:16px;margin:12px 0}.unread-label{display:inline-block;font-size:12px;color:var(--accent);margin-bottom:8px}article.unread{border-left:3px solid var(--accent)}h2{font-size:17px}p{margin:8px 0}time{font-size:12px;color:var(--muted)}article>div{display:flex;flex-wrap:wrap;gap:10px;margin-top:12px}</style>
